import shutil
import openpyxl
from datetime import datetime, date, timedelta

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

ws = wb.active if wb.active is not None else wb["Sheet1"]
vws = vals[ws.title]

last_value = None
for row in range(1, 12):
    v = vws.cell(row=row, column=1).value
    if v is None:
        continue
    if isinstance(v, str) and not v.strip():
        continue
    last_value = v

def extract_day_number(value):
    if isinstance(value, datetime):
        return value.day
    if isinstance(value, date):
        return value.day
    if isinstance(value, (int, float)):
        # If the cached value is an Excel date serial number, convert it.
        # For modern dates, this base works correctly.
        try:
            return (datetime(1899, 12, 30) + timedelta(days=float(value))).day
        except Exception:
            return None
    if isinstance(value, str):
        s = value.strip()
        try:
            return datetime.fromisoformat(s).day
        except Exception:
            try:
                import pandas as pd
                return pd.to_datetime(s).day
            except Exception:
                return None
    return None

result = extract_day_number(last_value) if last_value is not None else None
ws["B1"] = result

wb.save(OUT)

print("last_value:", last_value)
print("B1:", ws["B1"].value)
